{
  "measure_id": "MEAS-F8CD0BB9",
  "restatements": [
    {
      "clause_id": "§1",
      "text": "Prohibits any person from demonstrating within 100 feet of the entrance to an abortion facility while the facility is operating."
    }
  ],
  "findings": [
    {
      "id": "f1",
      "clause_id": "§1",
      "concern_id": "C24",
      "effect": "costs",
      "direction": null,
      "quote": "No person may demonstrate within 100 feet of the entrance",
      "mechanism": "Restricts freedom of speech by creating a geographic buffer zone where demonstrations are legally prohibited.",
      "certainty": "stated"
    },
    {
      "id": "f2",
      "clause_id": "§1",
      "concern_id": "C35",
      "effect": "advances",
      "direction": null,
      "quote": "No person may demonstrate within 100 feet of the entrance of a facility that provides abortion services",
      "mechanism": "Creates a buffer zone that physically distances demonstrators from patients and staff entering abortion facilities.",
      "certainty": "stated"
    },
    {
      "id": "f3",
      "clause_id": "§1",
      "concern_id": "C36",
      "effect": "costs",
      "direction": null,
      "quote": "No person may demonstrate within 100 feet of the entrance of a facility that provides abortion services",
      "mechanism": "Limits the ability of individuals to express opposition to abortion in close proximity to the facilities providing those services.",
      "certainty": "stated"
    }
  ],
  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Currently, demonstrations are permitted on public sidewalks outside these facilities as long as they follow general noise and traffic rules. This measure supersedes those general rules by creating a specific 100-foot no-demonstration buffer zone around abortion facilities during their hours of operation.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q3",
      "answer": "Patients seeking services and staff working at abortion facilities benefit from reduced proximity to demonstrators. Protesters and advocacy groups bear the cost of having to relocate their activities at least 100 feet away from the entrance.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Demonstrators will likely gather at the immediate edge of the 100-foot boundary. Law enforcement will be required to establish and enforce the exact 100-foot perimeter. The restriction is highly likely to face legal challenges regarding its compliance with First Amendment protections for speech in traditional public forums.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "The measure addresses the potential for intimidation, harassment, or physical obstruction of individuals entering abortion facilities. The 100-foot buffer zone physically separates protesters from the entrance to mitigate these issues.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q6",
      "answer": "Law enforcement agencies gain discretion in determining the exact boundaries of the buffer zone and in deciding what specific activities qualify as a \"demonstration\" under the law.",
      "disputed": false
    }
  ],
  "flags": [
    {
      "clause_id": "§1",
      "flag_id": "F1",
      "quote": "demonstrate",
      "note": "The text does not define what actions constitute a demonstration, leaving it ambiguous whether it includes silent prayer, holding signs, distributing literature, or only active protests."
    }
  ],
